"""Fresh CAPE episodes for the T1 confirmation, generated by CAPE's own harness (scripts/20_server_rollouts.py),
unchanged except that outputs go to the grey-box workspace (CAPE's project folders are never written).
Scenario specs are read from CAPE's capebench folder through a symlink.

python scripts/20_fresh_cape_rollouts.py actor=gemma4 split=core24b out_name=gb_gemma4_core24b_minus40414243 seeds='[40,41,42,43]'
"""
import importlib
import sys
from pathlib import Path

CAPE = Path("/home/arya/new_safety/cape")
sys.path.insert(0, str(CAPE / "src"))
sys.path.insert(0, str(CAPE / "scripts"))
srv = importlib.import_module("20_server_rollouts")
srv.REPO_ROOT = Path("/data/models/graybox_ws/cape_root")     # reads outputs/capebench (symlink), writes outputs/rollouts
if __name__ == "__main__":
    srv.main()
